var n=`0446-plokkfiskur`;var t=`world-0446`;var o=`IS`;var l=`northern-europe`;var r=4;var a=46;var s={en:`Plokkfiskur`,ua:`Плоккфіскур`};var u={en:`A traditional dish from Iceland, centered on potato, cod, whole cow milk, all-purpose flour. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ісландія. Основні складники: картопля, тріска, цільне коров'яче молоко, пшеничне борошно універсальне. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 19 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 19 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:19,i:[[`potato`,650,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 12 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 12 хвилин до готовності й м’якості.`,t:[`poaching`],m:12,i:[[`cod`,580,`g`],[`whole-cow-milk`,350,`ml`]]},{en:`Melt the fat, stir in flour and cook gently for about 8 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 8 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:8,i:[[`unsalted-butter`,65,`g`],[`all-purpose-flour`,45,`g`],[`whole-cow-milk`,270,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`yellow-onion`,140,`g`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`rye-bread`,4,`slice`]]}];var m={slug:n,id:t,country:`IS`,region:l,servings:4,minutes:46,title:s,text:u,steps:d};export{o as country,m as default,t as id,a as minutes,l as region,r as servings,n as slug,d as steps,u as text,s as title};